    await r.getByTestId('person-merge-into').selectOption({ label: intoName }, { timeout: 2000 });
  } catch {
    return false;
  }
  await r.getByTestId('person-merge').click();
  return until(page, async () => (await r.count()) === 0, r.getByTestId('person-error'), 'merge');
}

